import re,glob,os,collections
W='/tmp/claude-501/w/'
SUP={'NING':'NBBW','SHEN':'SZHT','YIWU':'YWLX','DONG':'DGRF','FOSH':'FSMJ','XIAM':'XMYD','HANG':'HZTY'}
NAMES={'NINGBO MINGTU HOUSEWARES CO., LTD.':'NBBW','SHENZHEN HETAI ELECTRIC APPLIANCE CO., LTD.':'SZHT','YIWU LANXIN TEXTILE CO., LTD.':'YWLX','DONGGUAN RUIFENG SILICONE PRODUCTS CO., LTD.':'DGRF','FOSHAN MINGJIA CERAMICS CO., LTD.':'FSMJ','XIAMEN YUANDA BAMBOO PRODUCTS CO., LTD.':'XMYD','NINGBO QISHENG STAINLESS STEEL CO., LTD.':'NBQS','HANGZHOU TIANYI GLASSWARE CO., LTD.':'HZTY'}
def parse(f):
    t=open(W+f+'.txt').read(); L=t.splitlines()
    sup=None
    for l in L[:6]:
        if l.strip().upper() in NAMES: sup=NAMES[l.strip().upper()]
    if not sup:
        for n,c in NAMES.items():
            if n.lower() in t.lower(): sup=c  # inspection reports
    out=[]
    for i,l in enumerate(L):
        m=re.match(r'^(\S+) ([a-z0-9][a-z0-9 ,.\-]+)$',l)
        if m and i+1<len(L) and re.search(r'[一-鿿]',L[i+1]):
            code,desc=m.groups()
            hs=None
            if i+2<len(L):
                m2=re.match(r'^(\d{4}\.\d{2}\.\d{4}) ',L[i+2]); hs=m2.group(1) if m2 else None
            out.append((code,desc,hs))
    return sup,out
if __name__=='__main__':
    c=collections.defaultdict(set)
    for f in sorted(os.listdir(W)):
        f=f[:-4]; sup,out=parse(f)
        if not sup: print('NOSUP',f)
        for code,desc,hs in out: c[(sup,code)].add((desc,hs))
    for k,v in sorted(c.items()): print(k,v)
